dofile('/probe.lua')
local defs=require('engine.interface.ActorTalents').talents_def
local wanted={'armour_training.png','assault.png','berserker.png','bloodbath.png','brutality.png','dark_gifts.png','daunting_presence.png','death_dance.png','defiling_touch.png','dwarf_resilience.png','fast_metabolism.png','fearless_cleave.png','frenzy.png','gloom.png','heightened_senses.png','last_stand.png','mortal_terror.png','perfect_strike.png','precise_strikes.png','predator.png','quick_recovery.png','rampage.png','repulsion.png','riposte.png','rush.png','shield_expertise.png','shield_pummel.png','shield_slam.png','shield_wall.png','slash.png','spell_shield.png','stalk.png','stoneskin.png','stunning_blow.png','sunder_armour.png','tenacity.png','thick_skin.png','unflinching_resolve.png','unnatural_body.png','vitality.png','warshout.png','weapon_combat.png','weapons_mastery.png'}
for _,icon in ipairs(wanted) do local found={} for id,t in pairs(defs) do if type(id)=='string' and type(t.image)=='string' and t.image:match('([^/]+)$')==icon then found[#found+1]=id..':'..tostring(t.type and t.type[1])..':'..tostring(t.name) end end table.sort(found); print('TALENT_ICON',icon,table.concat(found,',')) end
